#[test]
fn budget_preflight_rejects_forged_selection_and_mismatched_trace() {
    let subject = subject();
    let candidates = candidate_fixtures();
    let trace = make_trace(&subject, &candidates);
    let decision = must(decide_group_continuation_v1(&subject, &trace, &candidates));

    let mut forged = decision.clone();
    forged.selected_candidate_id = "abstain".to_owned();
    assert_eq!(
        preflight_group_future_cost_v1(&subject, &trace, &candidates, &forged, 1),
        Err(GroupSystem2Error::DecisionMismatch)
    );

    let mut altered = trace;
    altered.behavior_digest = digest("new-behavior");
    assert_eq!(
        preflight_group_future_cost_v1(&subject, &altered, &candidates, &decision, 1),
        Err(GroupSystem2Error::DecisionMismatch)
    );
}

#[test]
fn budget_preflight_denies_zero_and_over_remaining_future_cost() {
    let subject = subject();
    let candidates = candidate_fixtures();
    let trace = make_trace(&subject, &candidates);
    let decision = must(decide_group_continuation_v1(&subject, &trace, &candidates));
    assert_eq!(
        preflight_group_future_cost_v1(&subject, &trace, &candidates, &decision, 0),
        Err(GroupSystem2Error::ZeroFutureCost)
    );
    assert_eq!(
        preflight_group_future_cost_v1(&subject, &trace, &candidates, &decision, 96),
        Err(GroupSystem2Error::FutureCostExceedsRemaining {
            requested: 96,
            remaining: 95,
        })
    );

    let mut nearly_exhausted = trace;
    nearly_exhausted.cells[0].cost_micros = 99;
    let decision = must(decide_group_continuation_v1(
        &subject,
        &nearly_exhausted,
        &candidates,
    ));
    assert_eq!(
        preflight_group_future_cost_v1(&subject, &nearly_exhausted, &candidates, &decision, 2,),
        Err(GroupSystem2Error::FutureCostExceedsRemaining {
            requested: 2,
            remaining: 1,
        })
    );
}

#[test]
fn portfolio_receipt_replay_rejects_mutated_allocation_and_digest() {
    let original = [
        candidate("baseline", 0, 0, true),
        candidate("direction", 80, 0, false),
    ];
    let ctx = context(2);
    let limits = budget(2);
    let receipt = select_output_portfolio_v1(&ctx, &limits, &original)
        .expect("canonical portfolio selection");

    verify_output_portfolio_receipt_v1(&ctx, &limits, &original, &receipt)
        .expect("exact receipt is replayable");
    // Input ordering is not authority: the binding must survive the same
    // canonical permutation used by the selection digest.
    let reordered = [original[1].clone(), original[0].clone()];
    verify_output_portfolio_receipt_v1(&ctx, &limits, &reordered, &receipt)
        .expect("canonical inputs replay identically");

    let mut altered_weight = receipt.clone();
    altered_weight.allocations[0].weight = FixedQ32::ZERO;
    assert_eq!(
        verify_output_portfolio_receipt_v1(&ctx, &limits, &original, &altered_weight),
        Err(NduError::InvalidSolverReceipt("portfolio receipt replay"))
    );

    let mut altered_digest = receipt.clone();
    altered_digest.selection_digest = Digest32::of_bytes(b"forged-digest");
    assert_eq!(
        verify_output_portfolio_receipt_v1(&ctx, &limits, &original, &altered_digest),
        Err(NduError::InvalidSolverReceipt("portfolio receipt replay"))
    );

    let mut altered_generation = receipt.clone();
    altered_generation.generation = Generation::new(2).expect("nonzero generation");
    assert_eq!(
        verify_output_portfolio_receipt_v1(&ctx, &limits, &original, &altered_generation),
        Err(NduError::InvalidSolverReceipt("portfolio receipt replay"))
    );

    assert_eq!(receipt.future_window_digest, ctx.future_window_digest);
    let mut altered_window = receipt;
    altered_window.future_window_digest = Digest32::of_bytes(b"forged-future-window");
    assert_eq!(
        verify_output_portfolio_receipt_v1(&ctx, &limits, &original, &altered_window),
        Err(NduError::InvalidSolverReceipt("portfolio receipt replay"))
    );
}

#[test]
fn receipt_integrity_replay_rejects_tampered_fields() {
    let source = [
        candidate("baseline", 0, 0, true),
        candidate("direction", 80, 1, false),
    ];
    let state = context(source.len());
    let limits = budget(2);
    let receipt = select_output_portfolio_v1(&state, &limits, &source)
        .expect("deterministic advisory receipt");
    assert_eq!(
        receipt.disposition,
        OutputPortfolioDispositionV1::AdvisorySelection
    );
    verify_output_portfolio_receipt_v1(&state, &limits, &source, &receipt)
        .expect("untampered receipt must replay exactly");

    let mut tampered_resource = receipt.clone();
    tampered_resource.total_resource = FixedQ32::ZERO;
    let mut tampered_latency = receipt.clone();
    tampered_latency.total_latency = FixedQ32::ZERO;
    let mut tampered_disposition = receipt.clone();
    tampered_disposition.disposition = OutputPortfolioDispositionV1::NoChange;
    let mut tampered_frontier = receipt.clone();
    tampered_frontier.frontier.clear();
    let mut tampered_allocation = receipt.clone();
    tampered_allocation.allocations[0].weight = FixedQ32::ZERO;
    let mut tampered_digest = receipt;
    tampered_digest.selection_digest = Digest32::ZERO;

    for forged in [
        tampered_resource,
        tampered_latency,
        tampered_disposition,
        tampered_frontier,
        tampered_allocation,
        tampered_digest,
    ] {
        assert_eq!(
            verify_output_portfolio_receipt_v1(&state, &limits, &source, &forged)
                .expect_err("a forged advisory receipt must fail closed"),
            NduError::InvalidSolverReceipt("portfolio receipt replay")
        );
    }
}

#[test]
fn selection_digest_rejects_forged_candidate_snapshot_without_full_replay() {
    let candidates = [
        candidate("baseline", 0, 0, true),
        candidate("private-head", 60, 10, false),
    ];
    let context = context(candidates.len());
    let budget = budget(2);
    let receipt =
        select_output_portfolio_v1(&context, &budget, &candidates).expect("advisory receipt");
    let canonical = canonical_candidates(&context, &candidates).expect("canonical candidates");
    let covariance =
        canonical_covariance(&context, &candidates, &canonical).expect("canonical covariance");
    assert_eq!(
        digest_selection(&context, &budget, &canonical, &covariance, &receipt),
        receipt.selection_digest
    );
    // This is an intentionally invalid input for digest-only consumers:
    // complete replay would reject it, but the advertised selection hash
    // must also change to prevent acceptance without full replay.
    let mut foreign = canonical;
    foreign[0].snapshot_digest = Digest32::of_bytes(b"foreign-candidate-snapshot");
    assert_ne!(
        digest_selection(&context, &budget, &foreign, &covariance, &receipt),
        receipt.selection_digest
    );
}

